use std :: fmt ; use std :: path :: Path ; use std :: time :: Duration ; use colored :: Colorize ; use forge_api :: { Conversation , Environment , ForgeConfig , Metrics , Role , Usage , UserUsage } ; use forge_tracker :: VERSION ; use num_format :: { Locale , ToFormattedString } ; use crate :: display_constants :: markers ; use crate :: model :: ForgeCommandManager ; use std :: path :: PathBuf ; use forge_api :: { Environment , EventValue } ; use pretty_assertions :: assert_eq ; use fake :: { Fake , Faker } ; use forge_api :: Metrics ; use forge_domain :: { FileOperation , ToolKind } ; use chrono :: Utc ; use forge_api :: ConversationId ; use forge_domain :: { FileOperation , ToolKind } ; use super :: { Conversation , Metrics } ; use chrono :: Utc ; use forge_api :: ConversationId ; use super :: { Conversation , Metrics } ; use chrono :: Utc ; use forge_api :: { Context , ContextMessage , ConversationId , Role } ; use super :: { Conversation , Metrics } ; use super :: Info ; use forge_api :: Metrics ; use forge_domain :: { FileOperation , ToolKind } ; use forge_api :: Metrics ; use forge_domain :: { FileOperation , ToolKind } ; # [doc = " A structured information display builder for terminal output."] # [doc = ""] # [doc = " `Info` provides a consistent way to display hierarchical information with"] # [doc = " titles, key-value pairs, and values. It handles alignment, formatting, and"] # [doc = " color coding automatically."] # [doc = ""] # [doc = " # Display Conventions"] # [doc = ""] # [doc = " When using Info, follow these conventions for consistency:"] # [doc = ""] # [doc = " ## Keys (Labels)"] # [doc = " - Use **Title Case** for keys (e.g., \"Default Model\", \"API Key\")"] # [doc = " - Keep keys concise but descriptive"] # [doc = " - Keys are automatically right-aligned within sections"] # [doc = " - Keys are displayed in **green bold**"] # [doc = ""] # [doc = " ## Values"] # [doc = " - Use the constants from [`crate::display_constants`] for special values"] # [doc = " - For empty values: Use `placeholders::EMPTY` (`[empty]`)"] # [doc = " - For statuses: Use `status::ENABLED` (`[enabled]`) or `status::DISABLED`"] # [doc = "   (`[disabled]`)"] # [doc = " - For actual values: Use the raw value (e.g., \"gpt-4\", \"/home/user\")"] # [doc = ""] # [doc = " ## Sections"] # [doc = " - Use **UPPERCASE** for section titles"] # [doc = " - Section titles are displayed in **bold dimmed**"] # [doc = " - Each section groups related key-value pairs"] # [doc = " - Keys within a section are aligned to the longest key"] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```rust,ignore"] # [doc = " use crate::display_constants::{placeholders, status};"] # [doc = " use crate::info::Info;"] # [doc = ""] # [doc = " let info = Info::new()"] # [doc = "     .add_title(\"CONFIGURATION\")"] # [doc = "     .add_key_value(\"Model\", \"gpt-4\")"] # [doc = "     .add_key_value(\"Provider\", \"openai\")"] # [doc = "     .add_key_value(\"Status\", status::ENABLED)"] # [doc = "     .add_title(\"METRICS\")"] # [doc = "     .add_key_value(\"Tokens\", \"1000\")"] # [doc = "     .add_key_value(\"Cost\", \"$0.02\");"] # [doc = ""] # [doc = " println!(\"{}\", info);"] # [doc = " ```"] # [doc = ""] # [doc = " # Output Format"] # [doc = ""] # [doc = " ```text"] # [doc = " "] # [doc = " CONFIGURATION"] # [doc = "   model gpt-4"] # [doc = " provider openai"] # [doc = "   status [enabled]"] # [doc = ""] # [doc = " METRICS"] # [doc = " tokens 1000"] # [doc = "   cost $0.02"] # [doc = " ```"] # [derive (Default)] pub struct Info { sections : Vec < Section > , }